**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    string s;
    int pustych = 0;
    while (plik >> s) {
        string wynik = "";
        for (char c : s) {
            if (!isdigit(c)) {
                wynik += c;
            }
        }
        cout << s << " -> ";
        if (wynik.empty()) {
            cout << "(pusty)" << endl;
            pustych++;
        } else {
            cout << wynik << endl;
        }
    }
    cout << "Puste napisy: " << pustych << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdego napisu budujemy nowy napis, pomijajac cyfry. Funkcja `isdigit()` zwraca true dla znakow '0'-'9'.

Weryfikacja:
- abc123def: a,b,c,d,e,f -> "abcdef"
- 456: wszystkie cyfry -> "" -> (pusty)
- hello: brak cyfr -> "hello"
- w0rld: w,r,l,d -> "wrld"
- 789xyz: x,y,z -> "xyz"
- a1b2c3: a,b,c -> "abc"
- 999: wszystkie cyfry -> "" -> (pusty)
- test42: t,e,s,t -> "test"
Puste napisy: 2 ("456" i "999")
